<template><q-page class="caja-page q-pa-md"><div class="page-wrap"><div class="page-heading row items-center justify-between q-mb-lg"><div><h1 class="title-with-icon"><q-icon name="point_of_sale" color="green-8"/> Gestión de Caja</h1><p>Controla apertura y cierre de caja.</p></div><q-btn v-if="!sesion" color="green-8" icon="lock_open" label="Abrir caja" no-caps @click="tipo='abrir';dialog=true"/><q-btn v-else outline color="orange-8" icon="lock" label="Cerrar caja" no-caps @click="tipo='cerrar';dialog=true"/></div><q-banner v-if="!sesion" rounded class="closed-banner q-mb-lg"><template #avatar><q-icon name="lock"/></template>La caja está cerrada.</q-banner><CajaResumenCards :cards="cards" class="q-mb-lg"/><div class="row q-col-gutter-lg q-mb-lg"><div class="col-12 col-lg-7"><q-card flat bordered class="status-card"><q-card-section><div class="section-title"><q-icon name="fact_check"/> Resumen de la jornada</div><div class="status-row"><span>Caja y cajero</span><strong>{{sesion?`${sesion.caja} · ${sesion.cajero}`:'Sin sesión abierta'}}</strong></div><div class="status-row"><span>Apertura</span><strong>{{sesion?.apertura||'--'}}</strong></div><div class="status-row"><span>Saldo inicial</span><strong>Bs {{inicial.toFixed(2)}}</strong></div><div class="status-row"><span>Total de ventas</span><strong>Bs {{totalVentas.toFixed(2)}}</strong></div><div class="status-row"><span>Efectivo total recibido</span><strong>Bs {{efectivoTotal.toFixed(2)}}</strong></div><div class="status-row"><span>QR total recibido</span><strong>Bs {{qrTotal.toFixed(2)}}</strong></div><div class="status-row"><span>Pagos de crédito</span><strong>Bs {{pagosCredito.toFixed(2)}}</strong></div><div class="status-row credit-breakdown"><span>↳ Efectivo de crédito</span><strong>Bs {{creditoEfectivo.toFixed(2)}}</strong></div><div class="status-row credit-breakdown"><span>↳ QR de crédito</span><strong>Bs {{creditoQr.toFixed(2)}}</strong></div><div class="status-row"><span>Crédito pendiente</span><strong>Bs {{pendiente.toFixed(2)}}</strong></div><div class="status-row"><span>Saldo esperado</span><strong>Bs {{esperado.toFixed(2)}}</strong></div><div class="status-row"><span>Efectivo contado</span><strong>Bs {{contado.toFixed(2)}}</strong></div><div class="status-row"><span>Diferencia</span><strong>Bs {{diferencia.toFixed(2)}}</strong></div></q-card-section></q-card></div><div class="col-12 col-lg-5"><CajaMetodoResumen :metodos="metodos"/></div></div><CajaFiltros :model="filtros" @limpiar="limpiar" class="q-mb-lg"/><CajaSesiones :sesiones="sesiones" :pagina="pagina" :total-paginas="totalPaginas" @pagina="cambiarPagina" @detalle="verDetalle"/><CajaSesionDetalle v-model="dialogDetalle" :sesion="seleccionada"/><CajaDialog v-model="dialog" :tipo="tipo" :cajas="cajas" :resumen="resumen" @guardar="guardar"/></div></q-page></template>
<script setup>
import{computed,onMounted,reactive,ref,watch}from'vue';import{useQuasar}from'quasar';import{listarCajas,abrirCaja,cerrarCaja,listarSesionesCaja,obtenerSesionCajaAbierta}from'../../api/caja/caja';import CajaResumenCards from'../../components/caja/CajaResumenCards.vue';import CajaMetodoResumen from'../../components/caja/CajaMetodoResumen.vue';import CajaDialog from'../../components/caja/CajaDialog.vue';import CajaFiltros from'../../components/caja/CajaFiltros.vue';import CajaSesiones from'../../components/caja/CajaSesiones.vue';import CajaSesionDetalle from'../../components/caja/CajaSesionDetalle.vue';const $q=useQuasar();const dialog=ref(false),tipo=ref('abrir'),cajas=ref([]),sesion=ref(null),sesiones=ref([]),pagina=ref(1),totalPaginas=ref(1),dialogDetalle=ref(false),seleccionada=ref(null),filtros=reactive({busqueda:'',caja:'',desde:'',hasta:''}),inicial=ref(0),esperado=ref(0),contado=ref(0),efectivoTotal=ref(0),qrTotal=ref(0),pagosCredito=ref(0),creditoEfectivo=ref(0),creditoQr=ref(0),pendiente=ref(0),mixto=reactive({total:0,efectivo:0,qr:0});const totalVentas=computed(()=>efectivoTotal.value+qrTotal.value+mixto.total),diferencia=computed(()=>contado.value-esperado.value),cards=computed(()=>[{label:'Saldo esperado',value:`Bs ${esperado.value.toFixed(2)}`,icon:'account_balance_wallet',color:'green'},{label:'Total de ventas',value:`Bs ${totalVentas.value.toFixed(2)}`,icon:'point_of_sale',color:'blue'},{label:'Crédito pendiente',value:`Bs ${pendiente.value.toFixed(2)}`,icon:'credit_score',color:'orange'},{label:'Estado',value:sesion.value?'ABIERTA':'CERRADA',icon:'lock',color:'orange'}]),metodos=computed(()=>[{label:'Efectivo',value:efectivoTotal.value,icon:'payments',color:'green'},{label:'QR',value:qrTotal.value,icon:'qr_code_2',color:'blue'},{label:'Mixto - efectivo / QR',value:mixto.total,detalle:`Efectivo: Bs ${mixto.efectivo.toFixed(2)} · QR: Bs ${mixto.qr.toFixed(2)}`,icon:'call_split',color:'purple'},{label:'Crédito',value:pagosCredito.value,detalle:`Efectivo: Bs ${creditoEfectivo.value.toFixed(2)} · QR: Bs ${creditoQr.value.toFixed(2)} · Pendiente: Bs ${pendiente.value.toFixed(2)}`,icon:'credit_score',color:'orange'}]),resumen=computed(()=>({saldoInicial:inicial.value,efectivo:efectivoTotal.value,qr:qrTotal.value,mixto:mixto.total,mixtoEfectivo:mixto.efectivo,mixtoQr:mixto.qr,credito:pagosCredito.value,creditoEfectivo:creditoEfectivo.value,creditoQr:creditoQr.value,esperado:esperado.value}));function formato(s){const fecha=s.fechaApertura?new Date(s.fechaApertura):null;return{...s,fecha:s.fechaApertura?.slice(0,10)||'',fechaTexto:fecha?fecha.toLocaleDateString('es-BO'):'--',hora:fecha?fecha.toLocaleTimeString('es-BO'):'--',apertura:fecha?fecha.toLocaleString('es-BO'):'--',cierre:s.fechaCierre?new Date(s.fechaCierre).toLocaleString('es-BO'):'',caja:s.caja||`Caja ${s.idCaja}`,cajero:s.cajero||s.usuario||`Usuario ${s.idUsuario}`,inicial:Number(s.montoInicial||0),esperado:Number(s.montoEsperado||0),contado:Number(s.efectivoContado||0),efectivo:Number(s.efectivo||0),qr:Number(s.qr||0),mixto:Number(s.mixto||0),mixtoEfectivo:Number(s.mixtoEfectivo||0),mixtoQr:Number(s.mixtoQr||0),credito:Number(s.credito||0),pagosCredito:Number(s.pagosCredito||0),creditoPendiente:Number(s.creditoPendiente||0),creditoEfectivo:Number(s.creditoEfectivo||0),creditoQr:Number(s.creditoQr||0)}}function actualizar(){if(!sesion.value){inicial.value=esperado.value=contado.value=efectivoTotal.value=qrTotal.value=pagosCredito.value=creditoEfectivo.value=creditoQr.value=pendiente.value=0;Object.assign(mixto,{total:0,efectivo:0,qr:0});return}const s=sesion.value;inicial.value=s.inicial;esperado.value=s.esperado;contado.value=s.contado;efectivoTotal.value=s.efectivo+s.mixtoEfectivo;qrTotal.value=s.qr+s.mixtoQr;pagosCredito.value=s.pagosCredito;creditoEfectivo.value=s.creditoEfectivo;creditoQr.value=s.creditoQr;pendiente.value=s.creditoPendiente;Object.assign(mixto,{total:s.mixto,efectivo:s.mixtoEfectivo,qr:s.mixtoQr})}async function cargarSesion(){try{const[b]=await Promise.all([obtenerSesionCajaAbierta()]);sesion.value=b?formato(b):null;actualizar()}catch(e){sesion.value=null;actualizar()}}async function cargarHistorial(){try{const c=await listarSesionesCaja({page:pagina.value-1,size:6,buscar:filtros.busqueda||undefined,idCaja:filtros.caja?Number(filtros.caja):undefined,desde:filtros.desde||undefined,hasta:filtros.hasta||undefined});sesiones.value=(c?.content||[]).map(formato);totalPaginas.value=Math.max(1,c?.totalPages||1)}catch(e){$q.notify({type:'negative',message:e?.response?.data?.message||'No se pudo cargar el historial.'})}}async function cargar(){try{const a=await listarCajas();cajas.value=(a||[]).filter(x=>x.estado==='ACTIVA').map(x=>({label:x.nombre,value:x.idCaja}));await cargarSesion();await cargarHistorial()}catch(e){$q.notify({type:'negative',message:'No se pudo cargar Caja.'})}}async function guardar(d){try{if(tipo.value==='abrir')sesion.value=formato(await abrirCaja({idCaja:Number(d.caja),montoInicial:d.monto,observacion:d.observacion||null}));else{const c=await cerrarCaja(sesion.value.idSesionCaja,{efectivoContado:d.monto,observacion:d.observacion||null});sesiones.value=[formato(c),...sesiones.value];sesion.value=null}actualizar();dialog.value=false;await cargarHistorial();$q.notify({type:'positive',message:'Operación guardada correctamente.'})}catch(e){$q.notify({type:'negative',message:e?.response?.data?.message||'No se pudo guardar.'})}}function limpiar(){Object.assign(filtros,{busqueda:'',caja:'',desde:'',hasta:''});pagina.value=1;cargarHistorial()}function cambiarPagina(p){pagina.value=p;cargarHistorial()}function verDetalle(s){seleccionada.value=s;dialogDetalle.value=true}watch(()=>[filtros.busqueda,filtros.caja,filtros.desde,filtros.hasta],()=>{pagina.value=1;cargarHistorial()});onMounted(cargar)
</script><style scoped>.caja-page{min-height:100vh;background:#f5f7fa}.page-wrap{max-width:1440px;margin:auto}.title-with-icon{display:flex;align-items:center;gap:9px;color:#1b5e20;font-size:30px;margin:0;font-weight:900}.page-heading p{color:#789080;margin:0}.closed-banner{background:#fff4df;color:#916000;border:1px solid #f0d59f}.status-card{border-radius:15px;height:100%}.section-title{display:flex;align-items:center;gap:8px;color:#1b5e20;font-size:16px;font-weight:900;margin-bottom:12px}.status-row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #edf2ee;color:#627167}.status-row strong{color:#26352c;text-align:right}.credit-breakdown{padding:4px 0 4px 14px;font-size:12px;color:#829189}@media(max-width:700px){.title-with-icon{font-size:25px}.page-heading{gap:12px;align-items:flex-start;flex-direction:column}.page-heading .q-btn{width:100%}}</style>
